values
  ('red', '红汤', '死亡、犯罪、严重伤害或沉重真相驱动的暗黑题。', 'red', 10),
  ('black', '黑汤', '恐怖、异常、心理压迫、疑似超自然但可推理的题。', 'violet', 20),
  ('funny', '王八汤', '整蛊、荒诞、搞怪、反套路和轻度恶趣味题。', 'green', 30),
  ('weird', '变格汤', '文字游戏、规则反转、元叙事和题面陷阱题。', 'gold', 40),
  ('emotion', '情感汤', '亲情、爱情、友情和遗憾型反转题。', 'amber', 50),
