insert into public.soups (
insert into public.soup_cases (soup_id, solution, target_clue_count, answer_keywords)
values
  ('11111111-1111-4111-8111-111111111111', '男孩其实躲在衣柜里，红雨衣被另一个人穿走，用来制造“他已经离开”的假象。暴雨冲掉了门口的脚印，家人因此错过了真正离开者的线索。', 6, array['男孩', '红雨衣', '衣柜', '伪装', '暴雨', '脚印', '家人']::text[]),
  ('22222222-2222-4222-8222-222222222222', '那面“镜子”其实是双向镜。她以为自己每天独处，另一侧的人却一直在观察；那天她被带走后，镜面只映出空房间。', 5, array['镜子', '双向镜', '观察', '房间', '带走', '化妆']::text[]),
  ('33333333-3333-4333-8333-333333333333', '所谓不存在的楼层是医院隔离层。她因事故昏迷，错过了约定；醒来后所有人只说她“迟到”，却没人愿意直接说出病房真相。', 5, array['电梯', '楼层', '医院', '隔离', '昏迷', '迟到']::text[]),
  ('44444444-4444-4444-8444-444444444444', '“咖啡”不是饮品，而是这条街地下广播的暗号。老板说“没有咖啡”代表行动取消，所以收到暗号的人同时沉默下来。', 4, array['咖啡', '暗号', '老板', '街', '沉默', '取消']::text[]),
  ('55555555-5555-4555-8555-555555555555', '晚餐是失踪的母亲提前做好的。家人被改写了当天记忆，只记得围坐吃饭，却忘了做饭的人已经不在餐桌旁。', 5, array['晚餐', '母亲', '提前', '记忆', '家人', '餐桌']::text[]),
  ('a5b94a61-d34d-484b-8da3-7d0b697c0ba0', '夜班司机在死亡前就设置了影子反光，让人误以为他事后仍能行动。手套被故意留在空剧场，目的是保护真正的目击者。真正的关键不是密室，而是消息被触发的时间。', 5, array['夜班司机', '手套', '空剧场', '影子反光', '保护真正的目击者', '死亡', '时间']::text[]),
  ('65d01353-cf55-4faf-a44b-41a654a5da79', '独居画师在死亡前就设置了借名登记，让人误以为他事后仍能行动。钥匙扣被故意留在雨夜巷口，目的是转移赔偿责任。真正的关键不是密室，而是消息被触发的时间。', 5, array['独居画师', '钥匙扣', '雨夜巷口', '借名登记', '转移赔偿责任', '死亡', '时间']::text[]),
  ('dc5321ee-0f82-4a60-9fb1-bcb9c8c7c5c9', '仓库管理员在死亡前就设置了定时短信，让人误以为他事后仍能行动。旧手机被故意留在停业商场，目的是隐瞒真正到场时间。真正的关键不是密室，而是消息被触发的时间。', 5, array['仓库管理员', '旧手机', '停业商场', '定时短信', '隐瞒真正到场时间', '死亡', '时间']::text[]),
  ('71f1fa44-f055-4376-bbbf-7dbe3a199f85', '剧场检票员在死亡前就设置了倒放录音，让人误以为他事后仍能行动。收据被故意留在值班室，目的是替另一个人制造不在场证明。真正的关键不是密室，而是消息被触发的时间。', 5, array['剧场检票员', '收据', '值班室', '倒放录音', '替另一个人制造不在场证明', '死亡', '时间']::text[]),
  ('0f19c9d7-ea5b-467c-9f08-08bfd29665c4', '便利店店长在死亡前就设置了自动门记录，让人误以为他事后仍能行动。围巾被故意留在快递站，目的是把意外伪装成自行离开。真正的关键不是密室，而是消息被触发的时间。', 5, array['便利店店长', '围巾', '快递站', '自动门记录', '把意外伪装成自行离开', '死亡', '时间']::text[]),
