  ('fa59d1a5-39a8-4ab9-ac42-943c1ba5b25e', '录音带并没有自己移动，档案室被人提前布置了重复的脚步声。失眠的主播因为长期紧张产生判断偏差，而布置者这么做是房间结构被刻意改造。', 5, array['失眠的主播', '录音带', '档案室', '重复的脚步声', '房间结构被刻意改造', '布置', '判断偏差']::text[]),
  ('76d8acd8-2d23-462c-86af-e6a04b97d790', '值班灯并没有自己移动，地下通道被人提前布置了循环播放的声音。值夜护士因为长期紧张产生判断偏差，而布置者这么做是记忆被暗示扭曲。', 5, array['值夜护士', '值班灯', '地下通道', '循环播放的声音', '记忆被暗示扭曲', '布置', '判断偏差']::text[]),
