  ('d4142519-713f-431c-93d3-e4d99e422e52', '病历夹并没有自己移动，咨询室被人提前布置了被替换的照片。独居老人因为长期紧张产生判断偏差，而布置者这么做是为了测试他的恐惧反应。', 5, array['独居老人', '病历夹', '咨询室', '被替换的照片', '为了测试他的恐惧反应', '布置', '判断偏差']::text[]),
