  ('c14d7dc2-6a6e-4245-a4c4-be87fef31074', '失败原因不在剧情，而在“被删掉的问题”这张题卡的同音词。旁观者忽略了白板笔上的格式规则，所以回答虽然正确，却不是题目要求的那一种答案。', 4, array['旁观者', '白板笔', '同音词', '被删掉的问题', '规则', '格式', '答案']::text[]),
  ('c07fcb50-8e53-4e61-9061-9f47242d8faf', '退休教师不是放下了，而是终于发现提前录好的祝福。车票一直承载着一个迟来的告别，今年的变化说明让家人误以为自己还在附近。', 5, array['退休教师', '车票', '疗养院花园', '提前录好的祝福', '让家人误以为自己还在附近', '告别', '记忆']::text[]),
  ('bd0c7c4a-1bbf-479d-a7c3-406e84bcad15', '长途司机不是放下了，而是终于发现寄错地址的包裹。花束一直承载着一个迟来的告别，今年的变化说明把真相藏进日常习惯里。', 5, array['长途司机', '花束', '学校礼堂', '寄错地址的包裹', '把真相藏进日常习惯里', '告别', '记忆']::text[]),
  ('f93638a2-13e0-419a-b210-b7dd4cf5296f', '独自生活的女儿不是放下了，而是终于发现被保留的座位。拼图一直承载着一个迟来的告别，今年的变化说明想把告别伪装成普通一天。', 5, array['独自生活的女儿', '拼图', '老照片馆', '被保留的座位', '想把告别伪装成普通一天', '告别', '记忆']::text[]),
  ('93c23bd9-d279-4c28-a0b8-2d8337a0641f', '失联多年的朋友不是放下了，而是终于发现重复播放的留言。录音笔一直承载着一个迟来的告别，今年的变化说明不愿让对方带着愧疚生活。', 5, array['失联多年的朋友', '录音笔', '河边长椅', '重复播放的留言', '不愿让对方带着愧疚生活', '告别', '记忆']::text[]),
  ('a1a9025e-2651-4d08-a6e1-59c5432dc5bd', '疗养院护工不是放下了，而是终于发现迟到的快递。旧相册一直承载着一个迟来的告别，今年的变化说明保护一个迟来的承诺。', 5, array['疗养院护工', '旧相册', '旧书店', '迟到的快递', '保护一个迟来的承诺', '告别', '记忆']::text[]),
  ('68ad1e10-25cd-43b3-a597-d4e316c78245', '搬家工人不是放下了，而是终于发现未署名的字迹。生日蜡烛一直承载着一个迟来的告别，今年的变化说明让家人误以为自己还在附近。', 5, array['搬家工人', '生日蜡烛', '旧家客厅', '未署名的字迹', '让家人误以为自己还在附近', '告别', '记忆']::text[]),
  ('68005e37-5b9f-43a7-8ad6-60007c9f3af9', '旧书店老板不是放下了，而是终于发现提前录好的祝福。围巾一直承载着一个迟来的告别，今年的变化说明把真相藏进日常习惯里。', 5, array['旧书店老板', '围巾', '车站候车室', '提前录好的祝福', '把真相藏进日常习惯里', '告别', '记忆']::text[]),
  ('8d6dc57d-a808-486b-8fca-aee7f55a026d', '退休教师不是放下了，而是终于发现寄错地址的包裹。车票一直承载着一个迟来的告别，今年的变化说明想把告别伪装成普通一天。', 5, array['退休教师', '车票', '疗养院花园', '寄错地址的包裹', '想把告别伪装成普通一天', '告别', '记忆']::text[]),
  ('6fa9d9f6-2f2b-47c2-86cd-d94fe2e0173f', '长途司机不是放下了，而是终于发现被保留的座位。花束一直承载着一个迟来的告别，今年的变化说明不愿让对方带着愧疚生活。', 5, array['长途司机', '花束', '学校礼堂', '被保留的座位', '不愿让对方带着愧疚生活', '告别', '记忆']::text[]),
  ('d24b2943-bb8d-4b3e-a8dc-6262f25b0da4', '关键是时区设置错误。大家把学校走廊里的参照物看错了，杯子没有神秘移动，只是因为规则说明被省略了一半。', 4, array['图书管理员', '杯子', '学校走廊', '时区设置错误', '规则说明被省略了一半', '误会', '参照物']::text[]),
