  ('11111111-1111-4111-8111-111111111111', array['男孩', '孩子', '小孩', '衣柜']::text[], '是', '人物', '男孩主动躲了起来，家人看到的身影未必是他。'),
  ('11111111-1111-4111-8111-111111111111', array['红雨衣', '雨衣', '衣服']::text[], '是', '物品', '红雨衣遮住了体型和身份，是误认的关键。'),
  ('11111111-1111-4111-8111-111111111111', array['雨', '暴雨', '脚印', '晚上', '时间']::text[], '部分正确', '时间线', '暴雨让门口痕迹很快消失，时间判断被干扰。'),
  ('11111111-1111-4111-8111-111111111111', array['家人', '父母', '误会']::text[], '部分正确', '动机', '家人的判断来自他们看到的“红雨衣身影”。'),
  ('11111111-1111-4111-8111-111111111111', array['死', '死亡', '杀', '伤害']::text[], '否', null, null),
