  ('22222222-2222-4222-8222-222222222222', array['镜子', '玻璃', '反光']::text[], '部分正确', '物品', '那面“镜子”的作用不只是反射。'),
  ('22222222-2222-4222-8222-222222222222', array['她', '女人', '化妆']::text[], '是', '人物', '她一直相信自己只是独处。'),
